im = Image.open('.loop/refs/macos-calendar.png').convert('RGB')
W,H=im.size
# locate the blue chip fill (222,237,254) boxes in the grid area y>185
hits={}
for y in range(186,H):
    for x in range(243,W):
        p=im.getpixel((x,y))
        if abs(p[0]-222)<6 and abs(p[1]-237)<6 and abs(p[2]-254)<4:
            hits.setdefault(x,[]).append(y)
xs=sorted(hits)
# group xs into runs
runs=[];cur=[xs[0]]
for a,b in zip(xs,xs[1:]):
    if b-a<=1: cur.append(b)
    else: runs.append((cur[0],cur[-1])); cur=[b]
runs.append((cur[0],cur[-1]))
print('x-runs of blue fill:',runs)
for a,b in runs:
    ys=sorted(set(hits[a]))
    print(' xrun',a,b,'y',ys[0],ys[-1],'h',ys[-1]-ys[0]+1)
